const timers=new Set();
globalThis.window={setTimeout:(fn,ms)=>{const id=setTimeout(()=>{timers.delete(id);fn()},ms);timers.add(id);return id},clearTimeout:id=>{timers.delete(id);clearTimeout(id)},dispatchEvent:()=>{}};
