  {name:'K1 Max saved identity drift',host:'192.168.1.106:7125',model:'creality-k1-max',bound:'durable-max-id'},
];
let failures=0;
try{
 for(const item of cases){
  const config={id:'printer-1',name:item.model,host:item.host,profile:{preset:item.model},deviceIdentity:{dedupeSafe:true,stableId:'frontend-id'}};
  const snapshot={printerId:config.id,host:config.host,stableId:item.bound??'frontend-id',sessionEpoch:1,activePort:80,activeProtocol:'websocket',connected:true,phase:'ready',capabilities:{}};
  let staged=0;const calls=[];
  globalThis.__native=async(command,args)=>{
   calls.push({command,args});
   if(command==='printer_actor_upsert')return snapshot;
   if(command==='printer_actor_events_pending')return [];
   if(command==='transactional_upload_begin'){
    if(args.stableId!==snapshot.stableId||args.host!==snapshot.host)throw new Error('UPLOAD_ACTOR_IDENTITY_MISMATCH');
    staged=0;return {uploadId:'test-upload',receivedSize:0,chunkSize:65536};
   }
   if(command==='transactional_upload_chunk'){assert.equal(args.offset,staged);staged+=args.data.length;return staged}
   if(command==='transactional_upload_finish'){assert.equal(staged,bytes.length);return {path:'calibration.gcode',sha256:digest,remoteVerified:true}}
   if(command==='local_library_read_begin')return {readId:'read-test',size:bytes.length};
   if(command==='local_library_read_chunk')return {data:[...bytes],nextOffset:bytes.length,done:true,sha256:digest};
   if(command==='local_library_read_abort'||command==='transactional_upload_abort')return true;
   throw new Error('Unexpected command '+command);
  };
  const client=new MoonrakerClient(config);
  try{
   assert.equal(await client.connectActor(0),true,'actor registration');
   assert.equal(await client.uploadLocalLibrary('calibration.gcode',digest,'model:'+item.model),'calibration.gcode');
   assert.equal(await client.upload(new File([bytes],'calibration.gcode')),'calibration.gcode');
   assert.equal(calls.filter(x=>x.command==='transactional_upload_begin').length,2);
   client.applyActorSnapshot({...snapshot,printerId:'foreign-printer',stableId:'foreign-id',sessionEpoch:99});
   client.applyActorSnapshot({...snapshot,host:'192.168.1.200',stableId:'foreign-id',sessionEpoch:99});
   assert.equal(client.stableId(),snapshot.stableId,'foreign snapshots must not replace upload identity');
   client.applyActorSnapshot({...snapshot,stableId:'stale-id',sessionEpoch:0});
   assert.equal(client.stableId(),snapshot.stableId,'stale snapshots must not replace upload identity');
   // A different target must never inherit the previous durable identity.
   client.config={...client.config,id:'another-printer'};
   assert.equal(client.stableId(),'frontend-id');
   client.config={...client.config,id:config.id,host:'192.168.1.200'};
   assert.equal(client.stableId(),'frontend-id');
   console.log('PASS '+item.name+' — library and file uploads');
  }catch(error){failures++;console.error('FAIL '+item.name+': '+error.message)}
  finally{client.disconnect()}
 }
}finally{for(const id of timers)clearTimeout(id)}
if(process.argv.includes('--expect-baseline-failure')){
 assert.ok(failures>=4,'baseline must reproduce K1C endpoint and durable identity failures');
 console.log('Published R105 identity failure reproduced in '+failures+' scenarios');
}else{assert.equal(failures,0,'all upload target identity scenarios must pass')}

